from lib import *
S = SS('e18')
steps = [
    step("brotli(1.2.0)自带一份静态字典。573 字节的英文 HTML 样板(导航、页脚):gzip-9 333 字节,zstd-19 348,brotli q11 203,brotli q5 243;取其前 300 字节:214 / 215 / 122 / 153;同样长度的合成乱码词(我的随机音节词表):gzip-9 344,zstd-19 351,brotli q11 268,brotli q5 344——q5 在乱码上和 gzip 一样(344 对 344),在英文样板上却小 27%(243 对 333)。这个差别应该来自内置字典(我没有读 brotli 的字典文件,只是从对比推断);q11 在乱码上也比 gzip 小 22%,那部分来自更好的匹配和上下文建模。一页 13 KiB 的合成页面,q11 压到 3048,gzip-9 3863。", t=tl(S(1)), done=lidx(S(1), '英文 HTML 样板(导航'), mark=lidx(S(1), '合成乱码词'), b=bars([['英文样板 gzip-9', 333, '333'], ['英文样板 br q5', 243, '243'], ['乱码词 gzip-9', 344, '344'], ['乱码词 br q5', 344, '344']], 350, done=[1], mark=[2, 3]), kv=KV([['英文 HTML 样板', 'br q5 243 对 gzip 333(小 27%)'], ['合成乱码词', 'br q5 344 = gzip 344'], ['推断', '差别来自内置字典(没读字典文件)']], ['推断'])),
    step("较大的数据:一页 HTML(13723 字节):gzip-6 3878,gzip-9 3863,zstd-3 3898,zstd-19 3791,brotli q5 3764,q9 3774,q11 3048;200 条 products JSON Lines(72453 字节):gzip-6 16349,gzip-9 16125,zstd-3 16318,zstd-19 14773,br q5 15444,q9 15224,q11 12742;pages 8 MiB:gzip-6 1836858,gzip-9 1822313,zstd-3 1670198,zstd-19 1401606,br q5 1588548,q9 1536350,q11 1390770。同样“速度档”下三者相近,brotli q11 最小:一页 HTML 比 gzip-9 小 21%,200 条 JSON 小 21%。单个 HTTP 响应通常是这种几十 KB 的大小,所以 brotli 在这个场景里收益明显。", t=tl(S(2)), done=lidx(S(2), '一页 HTML 13 KiB'), mark=lidx(S(2), '200 条 products'), b=bars([['一页 HTML:gzip-9', 3863, '3863'], ['一页 HTML:br q11', 3048, '3048'], ['200 条 JSON:gzip-9', 16125, '16125'], ['200 条 JSON:br q11', 12742, '12742']], 16200, mark=[0, 2], done=[1, 3]), kv=KV([['一页 HTML', 'gzip-9 3863 → br q11 3048(小 21%)'], ['200 条 JSON', 'gzip-9 16125 → br q11 12742(小 21%)'], ['pages 8 MiB', 'zstd-19 1401606,br q11 1390770']], ['一页 HTML'])),
    step("按 Accept-Encoding 协商(本机服务器,服务器按偏好 br、zstd、gzip 选):requests 2.34.2 默认发出 Accept-Encoding: gzip, deflate, br, zstd(装了 brotli 和 zstandard 之后才会带上 br 和 zstd);服务器选了 br,2000 条 JSON(723399 字节)线上只传 129879 字节。逐个测:identity 线上 723399;gzip 150532;br 129879;zstd 138216;一页 HTML(13723 字节):identity 13723,gzip 3890,br 3764,zstd 3898。所有组合解码后都和原文一致。同样的 JSON 数据,br 比 gzip 少传 14%。", t=tl(S(3)), done=lidx(S(3), 'Accept-Encoding: br   '), mark=lidx(S(3), 'requests 2.34.2 默认发出'), b=bars([['identity', 723399, '723399'], ['gzip', 150532, '150532'], ['zstd', 138216, '138216'], ['br', 129879, '129879']], 730000, mark=[0], done=[3]), kv=KV([['requests 默认', 'gzip, deflate, br, zstd'], ['2000 条 JSON 线上字节', 'gzip 150532,zstd 138216,br 129879'], ['一页 HTML', 'gzip 3890,br 3764,zstd 3898']], ['requests 默认'])),
    step("已经压缩过或本来无法压缩的内容再压一次:1 MiB 随机字节(像 JPEG 或加密数据)gzip-6 压成 1048902,br q5 1048581,zstd-3 1048609,都比原文大;一份已经 gzip 过的文本(230952 字节)再压:gzip-6 231033,br q5 230957,zstd-3 230967,也都略大;原始文本 1048576 字节:gzip-6 230940,br q5 200268,zstd-3 209800。对图片、视频、已压缩的文件不要再启用 HTTP 压缩,白白花 CPU 还变大。", t=tl(S(4)), done=lidx(S(4), '原始文本(未压缩)'), mark=lidx(S(4), '随机字节'), b=bars([['随机字节 原始', 1048576, '1048576'], ['随机字节 gzip-6', 1048902, '1048902'], ['原始文本 gzip-6', 230940, '230940'], ['原始文本 br q5', 200268, '200268']], 1050000, mark=[1], done=[2, 3]), kv=KV([['随机字节', '压完更大(1048902 对 1048576)'], ['已 gzip 的文本', '再压没有收益'], ['原始文本', 'gzip-6 230940,br q5 200268']], ['随机字节'])),
    step("每个请求现压缩要花多少 CPU(一页 13 KiB HTML,中位数):gzip level 1 压成 4072 字节、44 微秒;level 6 3878、94 微秒(单核约每秒 10667 页);level 9 3863、134 微秒;zstd level 3 3898、26 微秒(约每秒 37915 页);zstd level 19 3791、2292 微秒;brotli q4 3874、93 微秒;q5 3764、150 微秒;q9 3774、218 微秒;q11 3048、10993 微秒(单核约每秒 91 页)。q5 以下速度和 gzip 一个量级,q11 慢 70–120 倍。动态内容用 q4–q5(或 zstd-3),静态文件预先用 q11 压好一次。", t=tl(S(5)), done=lidx(S(5), 'brotli q11'), mark=lidx(S(5), 'zstd level 3'), b=bars([['gzip level 6 微秒', 94, '94'], ['zstd level 3', 26, '26'], ['brotli q5', 150, '150'], ['brotli q11(千)', 10.993, '10993']], 160, mark=[1], done=[2]), kv=KV([['gzip level 6', '94 微秒/页'], ['brotli q5', '150 微秒/页'], ['brotli q11', '10993 微秒/页(约每秒 91 页)']], ['brotli q11'])),
    step("总耗时模型(估算,不是实测网络):压缩 + 字节数 × 8 / 带宽 + 解压,一页 13 KiB HTML。1 Mbit/s 下:identity 109.78 ms;gzip-6 31.14 ms;zstd-3 31.22;br q5 30.28;br q11 35.38(压缩 10.97 ms)。10 Mbit/s:10.98 / 3.22 / 3.15 / 3.18 / 13.44 ms。100 Mbit/s:1.10 / 0.43 / 0.35 / 0.47 / 11.24。1 Gbit/s:0.11 / 0.15 / 0.07 / 0.20 / 11.02。慢网络下压缩把时间降到约 1/4;快网络下现压缩已经不划算,q11 在现压缩时反而慢 100 倍。对静态文件预先 q11 压缩好,压缩时间不计入请求;现压缩的动态内容选 gzip-6 或 zstd-3。", t=tl(S(6)), done=lidx(S(6), 'zstd-3  '), mark=lidx(S(6), 'br q11'), b=bars([['1 Mbit/s identity ms', 109.78, '109.78'], ['1 Mbit/s zstd-3', 31.22, '31.22'], ['1 Gbit/s zstd-3', 0.07, '0.07'], ['1 Gbit/s br q11(现压缩)', 11.02, '11.02']], 112, done=[1, 2], mark=[3]), kv=KV([['1 Mbit/s', 'identity 109.78 ms,压缩后约 31 ms'], ['1 Gbit/s', 'zstd-3 0.07 ms,br q11 现压缩 11.02 ms'], ['结论', '慢网络压缩划算;现压缩别用高级别']], ['结论'])),
]
A = mkarte('e18', 18, '压缩原理,brotli,gzip,zstd,HTTP,Content-Encoding,Accept-Encoding,静态字典,Python,真实验证,动画演示',
    '在 HTTP 场景里比较 gzip、brotli、zstd:brotli q5 在英文 HTML 样板上比 gzip 小 27%(应来自内置字典)、在乱码词上与 gzip 相同;requests 装了 brotli 和 zstandard 后会发 gzip, deflate, br, zstd;随机数据再压变大;brotli q11 现压缩每页 11 ms;慢网络压缩划算、快网络现压缩高级别不划算。',
    '浏览器和 HTTP 客户端用 gzip、brotli、zstd 压缩响应。brotli 为什么能在小页面上更小?requests 默认会发什么?对已经压缩的内容再压会怎样?现压缩和预压缩怎么选?这篇在本机服务器上逐项测。',
    [('243 对 333', '573 字节英文 HTML 样板:brotli q5 与 gzip-9 的压缩后字节(合成乱码词上两者都是 344)'), ('129879 对 150532', '2000 条 JSON(723399 字节)线上传输字节:brotli 与 gzip'), ('10993 微秒', 'brotli q11 现压缩一页 13 KiB HTML 的耗时(gzip level 6 是 94 微秒)')],
    [('brotli 的字典', '<p>brotli 自带一份静态字典,里面是英文词和 HTML、JavaScript、CSS 的常见片段。实验里 q5 对合成乱码词和 gzip 一样大(344 字节),对英文 HTML 样板却小 27%;这个差别应该来自字典,但我没有读字典文件,只是推断。</p>'),
     ('常见响应大小上的差别', '<p>一页 13 KiB 的 HTML,brotli q11 比 gzip-9 小 21%;200 条 JSON 小 21%。几十 KB 的小响应是 HTTP 的典型大小,所以收益明显。</p>'),
     ('协商', '<p>客户端用 Accept-Encoding 声明支持的编码,服务器选一个。requests 2.34.2 在装了 brotli 和 zstandard 之后默认发 gzip, deflate, br, zstd;2000 条 JSON 线上 gzip 150532 字节、zstd 138216、br 129879。这也是 Vary: Accept-Encoding 的由来。</p>'),
     ('别压已经压缩的', '<p>随机字节(像 JPEG、加密数据)和已经压缩过的文本再压一次不会变小,还略大。HTTP 压缩应当只用于文本类内容。</p>'),
     ('现压缩的 CPU', '<p>q4–q5 和 gzip 一个量级,zstd-3 更快(26 微秒/页),q11 每页 11 ms。动态内容用 gzip-6、zstd-3 或 brotli q4–q5;静态文件预先用 q11 压好。</p>'),
     ('什么时候压缩划算', '<p>按“压缩 + 传输 + 解压”的估算:1 Mbit/s 下一页 109.78 ms 降到约 31 ms;1 Gbit/s 下 zstd-3 只有 0.07 ms,而 q11 现压缩是 11.02 ms,不划算。网络越快,压缩的收益越小,压缩的 CPU 开销越要留意。</p>')],
    steps,
    [ENV_E + '。brotli 1.2.0(Python 包,临时安装)、zstandard、zlib;本机 HTTP 服务器按 Accept-Encoding 选择编码,requests 2.34.2、urllib3 2.7.0;“合成乱码词”是随机音节拼成的,“英文 HTML 样板”是我写的一段典型导航页脚;第五节每种 30 或 300 次取中位数;第六节是用测得的体积和耗时算的估算,不是实测网络',
     '没有验证:brotli 字典文件的内容与大小(只从对比推断它的作用);真实网站的页面与 JS/CSS 文件;浏览器实际的解压行为;HTTP/2 头部压缩(HPACK);zstd 作为 Content-Encoding 在各浏览器里的支持情况;TCP 慢启动、多个请求并发对总耗时的影响'],
    'HTTP 压缩')
